<?php $money=static fn(float $v):string=>'KES '.number_format($v,2);$student=$student??[];$events=$events??[];$closing=(float)($closing_balance??0);$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??''); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Statement | EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f6f7fb;color:#172033}.wrap{max-width:1100px;margin:32px auto;padding:0 18px}.card{background:#fff;border:1px solid #e6e8ef;border-radius:12px;padding:20px;margin-bottom:16px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:11px;border-bottom:1px solid #eee;text-align:left}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn,a{display:inline-block;padding:9px 13px;border-radius:8px;text-decoration:none;background:#172033;color:#fff}input{padding:9px;border:1px solid #ccd1db;border-radius:8px}.right{text-align:right}</style></head><body><main class="wrap"><div class="actions"><a href="/finance/students/<?= (int)$student['id'] ?>/ledger">← Ledger</a><button class="btn" onclick="window.print()">Print</button></div><section class="card"><h1>Student Fee Statement</h1><h2><?= htmlspecialchars($student['first_name'].' '.$student['last_name']) ?></h2><p>Admission No: <?= htmlspecialchars($student['admission_no']) ?></p><form class="actions" method="get"><label>From <input type="date" name="from" value="<?= htmlspecialchars($from) ?>"></label><label>To <input type="date" name="to" value="<?= htmlspecialchars($to) ?>"></label><button class="btn">Apply</button></form></section><section class="card"><table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Description</th><th class="right">Debit</th><th class="right">Credit</th><th class="right">Balance</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= htmlspecialchars($event['date']) ?></td><td><?= htmlspecialchars(ucfirst($event['type'])) ?></td><td><?= htmlspecialchars($event['reference']) ?></td><td><?= htmlspecialchars($event['description']) ?></td><td class="right"><?= $event['debit']>0?$money((float)$event['debit']):'—' ?></td><td class="right"><?= $event['credit']>0?$money((float)$event['credit']):'—' ?></td><td class="right"><?= $money((float)$event['balance']) ?></td></tr><?php endforeach;if(!$events): ?><tr><td colspan="7">No ledger activity in this period.</td></tr><?php endif; ?></tbody><tfoot><tr><th colspan="6" class="right">Closing Balance</th><th class="right"><?= $money($closing) ?></th></tr></tfoot></table></section></main></body></html>
